WITH matched_keys AS (SELECT supplier_id, brand FROM products INTERSECT ALL SELECT supplier_id, brand FROM products WHERE cost <= 400), reconciled AS (SELECT s.* FROM products s INNER JOIN matched_keys k ON s.supplier_id = k.supplier_id AND s.brand = k.brand) SELECT supplier_id, APPROX_PERCENTILE(price, ARRAY(0.25, 0.5, 0.75)) AS price_quartiles, AVG(price) FILTER (WHERE brand = 'Stark') AS stark_avg_price, BIT_AND(stock_qty) AS stock_qty_bit_and, STDDEV_SAMP(price) AS price_stddev FROM reconciled GROUP BY supplier_id
